(1048331, 125972, 28742, '<td valign="top">Those "Landmarks" are moving...  ;-)</td>', 'Those "Landmarks" are moving...  ;-)', '2004-12-06 04:14:02.000000', NULL, 1),
(1048332, 126242, 28742, '<td valign="top">Too hazy to give it a high score. sorry.</td>', 'Too hazy to give it a high score. sorry.', '2004-12-06 04:14:25.000000', NULL, 1),
(1048335, 126302, 28742, '<td valign="top">What the...</td>', 'What the...', '2004-12-06 04:15:49.000000', NULL, 1),
