(1049434, 126191, 26464, '<td valign="top">nice job of framing, would''ve cropped off the car and junk at the bottom.<br/></td>', 'nice job of framing, would''ve cropped off the car and junk at the bottom.', '2004-12-06 20:48:11.000000', NULL, 1),
(1049435, 125540, 23458, '<td valign="top">Well you picked the right time of day - the lighting is really great, and you didn''t oversaturate the sky this time. But you really need to get a new subject. <br/> <br/>:P.</td>', 'Well you picked the right time of day - the lighting is really great, and you didn''t oversaturate the sky this time. But you really need to get a new subject.  :P.', '2004-12-06 20:49:48.000000', NULL, 1),
(1049438, 126041, 17837, '<td valign="top">a tad over exposed. You had the right idea, perhaps a half stop lower and you would have nailed it.</td>', 'a tad over exposed. You had the right idea, perhaps a half stop lower and you would have nailed it.', '2004-12-06 20:50:43.000000', NULL, 1),
(1049440, 125627, 20779, '<td valign="top">This HAS to ribbon. It is technically perfect, meets the challenge, and is simply breathtaking. This could sell a million in my opinion.</td>', 'This HAS to ribbon. It is technically perfect, meets the challenge, and is simply breathtaking. This could sell a million in my opinion.', '2004-12-06 20:51:58.000000', NULL, 1),
(1049442, 125790, 20779, '<td valign="top">One of my 10''s in the challenge. I love the playful spots of color, the geometrics, the lighting - everything about it.  Amazing photo with amazing depth.</td>', 'One of my 10''s in the challenge. I love the playful spots of color, the geometrics, the lighting - everything about it.  Amazing photo with amazing depth.', '2004-12-06 20:53:35.000000', NULL, 1),
(1049444, 126214, 20779, '<td valign="top">This just shines. I can''t get enough of it. One of my 10''s in the challenge and a great interpretation for landmark. This would also make a wonderful print.</td>', 'This just shines. I can''t get enough of it. One of my 10''s in the challenge and a great interpretation for landmark. This would also make a wonderful print.', '2004-12-06 20:55:01.000000', NULL, 1),
(1049450, 126301, 17837, '<td valign="top">too much negative space. Tighter crop would work way better here.</td>', 'too much negative space. Tighter crop would work way better here.', '2004-12-06 21:19:05.000000', NULL, 1),
(1049453, 126202, 17837, '<td valign="top">I swear I just saw this photo...</td>', 'I swear I just saw this photo...', '2004-12-06 21:21:07.000000', NULL, 1),
(1049454, 125791, 23394, '<td valign="top">you have brought this sculpture to life.  my God, this evokes a scream of raging silence!  i would love to see before and afters on this, just to better understand how you are able to draw this image out.  i''d also love to see a dead-on documentary style shot just to compare what everybody else sees with what you saw.  the despair and desolation and anguish are almost too much to bear.  this is easily one of the most powerful images on this site!</td>', 'you have brought this sculpture to life.  my God, this evokes a scream of raging silence!  i would love to see before and afters on this, just to better understand how you are able to draw this image out.  i''d also love to see a dead-on documentary style shot just to compare what everybody else sees with what you saw.  the despair and desolation and anguish are almost too much to bear.  this is easily one of the most powerful images on this site!', '2004-12-06 21:21:14.000000', NULL, 1),
(1049455, 126221, 29486, '<td valign="top">Nice attempt at a different angle for the capitol but it''s a bit too busy. Also it looks like the angle is a bit tilted</td>', 'Nice attempt at a different angle for the capitol but it''s a bit too busy. Also it looks like the angle is a bit tilted', '2004-12-06 21:21:33.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(1049459, 125540, 23394, '<td valign="top">you definitely shot this at the right time.  the lighting, shadows, and sky are come together wonderfully.  great composition.  i can''t think of anything i could do to improve the shot or its presentation.  good job!</td>', 'you definitely shot this at the right time.  the lighting, shadows, and sky are come together wonderfully.  great composition.  i can''t think of anything i could do to improve the shot or its presentation.  good job!', '2004-12-06 21:24:07.000000', NULL, 1),
(1049460, 126212, 17837, '<td valign="top">the off centerness of this is distracting for me, perhaps sliding a bit further over and making it align vertically would work better.</td>', 'the off centerness of this is distracting for me, perhaps sliding a bit further over and making it align vertically would work better.', '2004-12-06 21:24:14.000000', NULL, 1),
(1049462, 124710, 17837, '<td valign="top">A tad over exposed, perhaps a 1/2 stop over.</td>', 'A tad over exposed, perhaps a 1/2 stop over.', '2004-12-06 21:27:52.000000', NULL, 1),
(1049464, 126082, 20941, '<td valign="top">great shot, really well done in b/w</td>', 'great shot, really well done in b/w', '2004-12-06 21:29:29.000000', NULL, 1),
(1049465, 126041, 23394, '<td valign="top">maybe it''s me, but this feels over processed.  i''m not sure what i would expect to see if i walked up on this scene at this time of day, but i''m pretty sure this is not it.  when i see an image like this, i wonder what you were thinking when you saw it.  did you see what you''ve submitted? or did you find your submission after you started post-processing?  you have definitely delivered a polished, eye-catching image of a universally recognized landmark.  i''m just curious as to how you feel about the work...<br/> <br/>it does feel a little too bright at the bottom; the flares are a little too strong.</td>', 'maybe it''s me, but this feels over processed.  i''m not sure what i would expect to see if i walked up on this scene at this time of day, but i''m pretty sure this is not it.  when i see an image like this, i wonder what you were thinking when you saw it.  did you see what you''ve submitted? or did you find your submission after you started post-processing?  you have definitely delivered a polished, eye-catching image of a universally recognized landmark.  i''m just curious as to how you feel about the work... it does feel a little too bright at the bottom; the flares are a little too strong.', '2004-12-06 21:31:38.000000', NULL, 1),
(1049473, 124877, 17837, '<td valign="top">Diffuse glow doesnt work well in this case</td>', 'Diffuse glow doesnt work well in this case', '2004-12-06 21:35:17.000000', NULL, 1),
(1049477, 126162, 12362, '<td valign="top">This shot has very attractive colors. It appeals to me very much : ) 9</td>', 'This shot has very attractive colors. It appeals to me very much : ) 9', '2004-12-06 21:36:25.000000', NULL, 1),
(1049478, 125854, 23394, '<td valign="top">incredible range of colors.  love your treatment of the clouds (or should i say non-treatment?  they don''t look overly burned or dodged.  i mean, i don''t have this most critical eye, but those clouds don''t even look like you touched them up at all!).<br/> <br/>i also appreciate your take on the challenge.  i hope you don''t hammered for not shooting a building or statue, because this is really an exquisite image.  great timing, great job!  good luck!</td>', 'incredible range of colors.  love your treatment of the clouds (or should i say non-treatment?  they don''t look overly burned or dodged.  i mean, i don''t have this most critical eye, but those clouds don''t even look like you touched them up at all!). i also appreciate your take on the challenge.  i hope you don''t hammered for not shooting a building or statue, because this is really an exquisite image.  great timing, great job!  good luck!', '2004-12-06 21:37:16.000000', NULL, 1),
(1049479, 126242, 12362, '<td valign="top">Nice shot, maybe bump up the saturation, it looks a bit bland but there are some nice colors that are hiding within.</td>', 'Nice shot, maybe bump up the saturation, it looks a bit bland but there are some nice colors that are hiding within.', '2004-12-06 21:37:22.000000', NULL, 1),
(1049481, 126291, 12362, '<td valign="top">Nice sky and nice colors. Altho the parking lot doesnt do it for me.</td>', 'Nice sky and nice colors. Altho the parking lot doesnt do it for me.', '2004-12-06 21:37:54.000000', NULL, 1),
(1049482, 125030, 12362, '<td valign="top">Nice emotional pic, 7</td>', 'Nice emotional pic, 7', '2004-12-06 21:38:23.000000', NULL, 1),
(1049484, 125656, 12362, '<td valign="top">The composition is a bit simple for me. Maybe try backing up and shooting it with its surroundings?</td>', 'The composition is a bit simple for me. Maybe try backing up and shooting it with its surroundings?', '2004-12-06 21:38:53.000000', NULL, 1),
(1049486, 126214, 12362, '<td valign="top">Really gives the you the feel of an old wester. Is that a person in that window or a ghost? Freaky.</td>', 'Really gives the you the feel of an old wester. Is that a person in that window or a ghost? Freaky.', '2004-12-06 21:39:46.000000', NULL, 1),
(1049488, 126203, 12362, '<td valign="top">Very nice, it might have been better if you had moved back to capture more sky and landscape?</td>', 'Very nice, it might have been better if you had moved back to capture more sky and landscape?', '2004-12-06 21:40:44.000000', NULL, 1),
(1049490, 126119, 12362, '<td valign="top">No critique needed. Excellent! 9</td>', 'No critique needed. Excellent! 9', '2004-12-06 21:41:43.000000', NULL, 1),
(1049492, 126166, 12362, '<td valign="top">The border works very well for this shot IMO. What do you think of it in black&amp;white or sepia?</td>', 'The border works very well for this shot IMO. What do you think of it in black&white or sepia?', '2004-12-06 21:42:22.000000', NULL, 1),
(1049495, 126177, 20941, '<td valign="top">great composition, color and clarity for this familiar landmark</td>', 'great composition, color and clarity for this familiar landmark', '2004-12-06 21:43:00.000000', NULL, 1),
(1049497, 125381, 12362, '<td valign="top">Did you intend for the tree to be part of the composition?<br/>In my opinion it distracts. 6</td>', 'Did you intend for the tree to be part of the composition?In my opinion it distracts. 6', '2004-12-06 21:43:18.000000', NULL, 1),
(1049499, 125854, 12362, '<td valign="top">So simple yet so NICE!!. Its great to see a shot like this without power lines in the shot, I have a million shots like this around my town but there are lines everywhere that ruin the shot. GREAT color and composition. 8</td>', 'So simple yet so NICE!!. Its great to see a shot like this without power lines in the shot, I have a million shots like this around my town but there are lines everywhere that ruin the shot. GREAT color and composition. 8', '2004-12-06 21:44:16.000000', NULL, 1),
(1049500, 126041, 20941, '<td valign="top">stunning shot, beautifully done!</td>', 'stunning shot, beautifully done!', '2004-12-06 21:44:45.000000', NULL, 1),
(1049504, 126300, 23394, '<td valign="top">i don''t think this is one of the better interpretations of haystack.  you might want to look through zoomdak''s work for some other treatments of this subject.</td>', 'i don''t think this is one of the better interpretations of haystack.  you might want to look through zoomdak''s work for some other treatments of this subject.', '2004-12-06 21:45:47.000000', NULL, 1),
(1049505, 126114, 25397, '<td valign="top">I love the sharpness and shutter speed, looks like a videogame (In a good way) :-)</td>', 'I love the sharpness and shutter speed, looks like a videogame (In a good way) :-)', '2004-12-06 21:45:53.000000', NULL, 1),
(1049506, 125874, 12362, '<td valign="top">Nice idea, the houses being visible distract and since they are out of focus it just makes it worse. I would suggest maybe burning out the detail in the houses? Good shot.</td>', 'Nice idea, the houses being visible distract and since they are out of focus it just makes it worse. I would suggest maybe burning out the detail in the houses? Good shot.', '2004-12-06 21:46:00.000000', NULL, 1),
(1049509, 125791, 12362, '<td valign="top">Powerful.<br/>It looks like you used duotones, its stronger with this. 9</td>', 'Powerful.It looks like you used duotones, its stronger with this. 9', '2004-12-06 21:46:57.000000', NULL, 1),
(1049510, 125789, 25397, '<td valign="top">I really like the colors, one of my favourites so far. I just really dont think that white border really suits it well.</td>', 'I really like the colors, one of my favourites so far. I just really dont think that white border really suits it well.', '2004-12-06 21:47:27.000000', NULL, 1),
(1049511, 125121, 12362, '<td valign="top">The mascot isnt visible that much, maybe a longer shutter speed or changing the composition and not having bright lights behind the picture.</td>', 'The mascot isnt visible that much, maybe a longer shutter speed or changing the composition and not having bright lights behind the picture.', '2004-12-06 21:47:43.000000', NULL, 1),
(1049513, 126250, 12362, '<td valign="top">Very nice black and white. 7</td>', 'Very nice black and white. 7', '2004-12-06 21:48:00.000000', NULL, 1),
(1049514, 125284, 25397, '<td valign="top">Woohoo Canada!. That''s what my back yard looks like right now.</td>', 'Woohoo Canada!. That''s what my back yard looks like right now.', '2004-12-06 21:48:41.000000', NULL, 1),
(1049516, 125709, 12362, '<td valign="top">Very nice soft look to the buildings. It looks a bit crowded tho.....maybe not cropping it too much would help that?</td>', 'Very nice soft look to the buildings. It looks a bit crowded tho.....maybe not cropping it too much would help that?', '2004-12-06 21:48:51.000000', NULL, 1),
(1049517, 126255, 12362, '<td valign="top">Nice, the building in the background looks just like something out of Greece. 7</td>', 'Nice, the building in the background looks just like something out of Greece. 7', '2004-12-06 21:49:19.000000', NULL, 1),
(1049521, 126272, 12362, '<td valign="top">Great sky in this shot. Black and white works very well. The only suggestion I have is maybe focus on one building. 8</td>', 'Great sky in this shot. Black and white works very well. The only suggestion I have is maybe focus on one building. 8', '2004-12-06 21:50:07.000000', NULL, 1),
(1049522, 125540, 25397, '<td valign="top">Hmm...I wonder who it could be? ;-)<br/> <br/>Excellent, you''ve really improved with this since your last picture. I really like the gold sun on the face, did you shoot it at morning time?</td>', 'Hmm...I wonder who it could be? ;-) Excellent, you''ve really improved with this since your last picture. I really like the gold sun on the face, did you shoot it at morning time?', '2004-12-06 21:50:30.000000', NULL, 1),
(1049525, 126039, 25397, '<td valign="top">I think  the angle of this shot makes the whole feeling of "flying," its so great!</td>', 'I think  the angle of this shot makes the whole feeling of "flying," its so great!', '2004-12-06 21:51:48.000000', NULL, 1),
(1049526, 125619, 12362, '<td valign="top">I really like how the train is coming out of the top corner of the image.<br/>The border works very well in this shot. The soft focus is beautiful.<br/>The water in the background has a nice reflection. But the subject just does not do it for me, better subject =9  ...............7</td>', 'I really like how the train is coming out of the top corner of the image.The border works very well in this shot. The soft focus is beautiful.The water in the background has a nice reflection. But the subject just does not do it for me, better subject =9  ...............7', '2004-12-06 21:51:52.000000', NULL, 1),
(1049527, 126295, 7485, '<td valign="top">Interesting photo, but ruined by the massive compression artifacts. The file is only 70KB, that''s less than half of DPC''s limit. You should generally try to compress your images to just below the limit.</td>', 'Interesting photo, but ruined by the massive compression artifacts. The file is only 70KB, that''s less than half of DPC''s limit. You should generally try to compress your images to just below the limit.', '2004-12-06 21:51:55.000000', NULL, 1),
(1049531, 126038, 25397, '<td valign="top">I''m not so sure of many people will appreciate this like I do. :)</td>', 'I''m not so sure of many people will appreciate this like I do. :)', '2004-12-06 21:53:09.000000', NULL, 1),
(1049532, 126230, 23394, '<td valign="top">i hope ya''ll had fun.  i''m not one to believe in conspiracy theories, but i really would have expected 3 or more images of the washington monument before 3 of these.</td>', 'i hope ya''ll had fun.  i''m not one to believe in conspiracy theories, but i really would have expected 3 or more images of the washington monument before 3 of these.', '2004-12-06 21:53:48.000000', NULL, 1),
(1049533, 126142, 23394, '<td valign="top">i hope ya''ll had fun.  i''m not one to believe in conspiracy theories, but i really would have expected 3 or more images of the washington monument before 3 of these.</td>', 'i hope ya''ll had fun.  i''m not one to believe in conspiracy theories, but i really would have expected 3 or more images of the washington monument before 3 of these.', '2004-12-06 21:53:59.000000', NULL, 1),
(1049534, 126202, 23394, '<td valign="top">i hope ya''ll had fun.  i wonder how many viewers are going to notice the bird eating the moon?  that makes this one the best of the bunch for me.  i''m not one to believe in conspiracy theories, but i really would have expected 3 or more images of the washington monument before 3 of these.</td>', 'i hope ya''ll had fun.  i wonder how many viewers are going to notice the bird eating the moon?  that makes this one the best of the bunch for me.  i''m not one to believe in conspiracy theories, but i really would have expected 3 or more images of the washington monument before 3 of these.', '2004-12-06 21:54:08.000000', NULL, 1),
(1049536, 125121, 23394, '<td valign="top">the horizon is really tilted, and the blue of the hen is getting lost in the dark.  maybe if you had shot it a bit earlier?</td>', 'the horizon is really tilted, and the blue of the hen is getting lost in the dark.  maybe if you had shot it a bit earlier?', '2004-12-06 21:56:42.000000', NULL, 1),
(1049541, 125862, 23394, '<td valign="top">oouu, this is tough...do i like day bean or night bean better?</td>', 'oouu, this is tough...do i like day bean or night bean better?', '2004-12-06 21:57:41.000000', NULL, 1),
(1049542, 126226, 12362, '<td valign="top">It is a bit dark for my taste. Maybe try a longer shutter speed next time?</td>', 'It is a bit dark for my taste. Maybe try a longer shutter speed next time?', '2004-12-06 21:57:46.000000', NULL, 1),
(1049543, 126283, 23394, '<td valign="top">oouu, this is tough...do i like day bean or night bean better?</td>', 'oouu, this is tough...do i like day bean or night bean better?', '2004-12-06 21:57:49.000000', NULL, 1),
(1049544, 125957, 12362, '<td valign="top">Great idea, great colors, great picture. 8</td>', 'Great idea, great colors, great picture. 8', '2004-12-06 21:58:13.000000', NULL, 1),
(1049547, 126008, 22384, '<td valign="top">The fact that this is a peace monument makes this shot brilliant.  The world is "ever late" when acknowledging peace. The red jacket symbolizes, for me, the bloodshed when we ignore peace. The subject facing to the right is hopeful, as is the monument, and the storm clouds in the upper right corner of the frame indicate that trouble is always brewing on the horizon, and his hopefulness may or may be for naught.  That is my take anyway. So captivating and thought-provoking. I knew it was there... I just needed to educate myself. Many thanks for this image. A rare 10.</td>', 'The fact that this is a peace monument makes this shot brilliant.  The world is "ever late" when acknowledging peace. The red jacket symbolizes, for me, the bloodshed when we ignore peace. The subject facing to the right is hopeful, as is the monument, and the storm clouds in the upper right corner of the frame indicate that trouble is always brewing on the horizon, and his hopefulness may or may be for naught.  That is my take anyway. So captivating and thought-provoking. I knew it was there... I just needed to educate myself. Many thanks for this image. A rare 10.', '2004-12-06 21:58:39.000000', NULL, 1),
(1049548, 125024, 7485, '<td valign="top">Great tower, but I''d prefer a litle less foreground, like cropping off the bottom half inch or so.</td>', 'Great tower, but I''d prefer a litle less foreground, like cropping off the bottom half inch or so.', '2004-12-06 21:58:59.000000', NULL, 1),
(1049549, 125059, 12362, '<td valign="top">It looks as if you are not taking full advantage of the size allowance. Just a little tip: If you have photoshop, when you save, save for WEB, and then adjust. Good luck.</td>', 'It looks as if you are not taking full advantage of the size allowance. Just a little tip: If you have photoshop, when you save, save for WEB, and then adjust. Good luck.', '2004-12-06 21:59:20.000000', NULL, 1),
(1049552, 126261, 12362, '<td valign="top">The reflection of the two towers and color in this photo do it for me. 8</td>', 'The reflection of the two towers and color in this photo do it for me. 8', '2004-12-06 22:00:42.000000', NULL, 1),
(1049553, 125030, 22384, '<td valign="top">The look on her face says it all. Great idea to get down and shoot this at her level. Strong composition and message. Daring and creative take on this challenge. I would like to see this image a little sharper, but given all the other strengths in this photo, that seems pretty petty of me. Great shot!</td>', 'The look on her face says it all. Great idea to get down and shoot this at her level. Strong composition and message. Daring and creative take on this challenge. I would like to see this image a little sharper, but given all the other strengths in this photo, that seems pretty petty of me. Great shot!', '2004-12-06 22:00:49.000000', NULL, 1),
(1049555, 126152, 23394, '<td valign="top">interesting take on the challenge, shooting a landmark from the inside.  while this is a beautiful image (and one that i am sure was not that easy to capture), it doesn''t really convey a sense of the landmark itself.  hopefully for you the voters won''t hammer you for your vision.</td>', 'interesting take on the challenge, shooting a landmark from the inside.  while this is a beautiful image (and one that i am sure was not that easy to capture), it doesn''t really convey a sense of the landmark itself.  hopefully for you the voters won''t hammer you for your vision.', '2004-12-06 22:01:05.000000', NULL, 1),
(1049556, 126270, 12362, '<td valign="top">I love these kinds of shots. Too bad the building is a bit underexposed but thats the problem with wanting to expose both (you did a mighty good job).<br/>Colors are great 8</td>', 'I love these kinds of shots. Too bad the building is a bit underexposed but thats the problem with wanting to expose both (you did a mighty good job).Colors are great 8', '2004-12-06 22:01:38.000000', NULL, 1),
(1049557, 125630, 22384, '<td valign="top">How in the world did you get them to turn on all their lights? Stunning home and image.</td>', 'How in the world did you get them to turn on all their lights? Stunning home and image.', '2004-12-06 22:01:52.000000', NULL, 1),
(1049562, 126172, 12362, '<td valign="top">Nice pattern in the sky. Very nice shot and nice color.<br/>My only problem with this shot is that the building is very far and can barely see it. 7</td>', 'Nice pattern in the sky. Very nice shot and nice color.My only problem with this shot is that the building is very far and can barely see it. 7', '2004-12-06 22:02:48.000000', NULL, 1),
(1049565, 125789, 12362, '<td valign="top">Great silhouette and nice colors. 8</td>', 'Great silhouette and nice colors. 8', '2004-12-06 22:04:39.000000', NULL, 1),
(1049570, 125284, 23394, '<td valign="top">auugh, don''t you just love it when the weather changes?!  i''m glad you went on and submitted...it definitely gave me a grin.  i''ll give it a 7, just because i know there''s something recognizable back there.  i''ll also suggest you go rent jim jarmusch''s first movie, "Stranger Than Paradise"; there is this one really incredible scene that takes place on the edge of lake erie, and that scene was the first thing i thought of when i saw this image.  good luck.</td>', 'auugh, don''t you just love it when the weather changes?!  i''m glad you went on and submitted...it definitely gave me a grin.  i''ll give it a 7, just because i know there''s something recognizable back there.  i''ll also suggest you go rent jim jarmusch''s first movie, "Stranger Than Paradise"; there is this one really incredible scene that takes place on the edge of lake erie, and that scene was the first thing i thought of when i saw this image.  good luck.', '2004-12-06 22:06:30.000000', NULL, 1),
(1049572, 125336, 23394, '<td valign="top">the colors are absolutely brilliant.  this is going right in my faves!  awesome job.</td>', 'the colors are absolutely brilliant.  this is going right in my faves!  awesome job.', '2004-12-06 22:07:37.000000', NULL, 1),
(1049573, 126227, 12362, '<td valign="top">Very nice tones. The only thing that distracts is the building in the background. I was geting an old school feeling but that modern building brought me back to reality : )</td>', 'Very nice tones. The only thing that distracts is the building in the background. I was geting an old school feeling but that modern building brought me back to reality : )', '2004-12-06 22:09:21.000000', NULL, 1),
(1049576, 125225, 22384, '<td valign="top">What a powerful shot. Ah, yes, the days. This does age me.</td>', 'What a powerful shot. Ah, yes, the days. This does age me.', '2004-12-06 22:11:06.000000', NULL, 1),
(1049578, 125933, 14986, '<td valign="top">I like the time you chose to shoot this.  I think the angle is a little extreme, but better than straight up.  Nice clarity and exposure. Overall a good shot.</td>', 'I like the time you chose to shoot this.  I think the angle is a little extreme, but better than straight up.  Nice clarity and exposure. Overall a good shot.', '2004-12-06 22:12:53.000000', NULL, 1),
(1049579, 125425, 14986, '<td valign="top">Cool lines and shading with the way the light is hitting this.  I just feel like it''s missing something to give it that little extra wow factor.</td>', 'Cool lines and shading with the way the light is hitting this.  I just feel like it''s missing something to give it that little extra wow factor.', '2004-12-06 22:13:48.000000', NULL, 1),
(1049581, 125442, 14986, '<td valign="top">I really like the idea here.  I like having the trees there, but they really almost seem to overwhelm the focus on the building imo.   Still, one of the better shots I"ve seen.</td>', 'I really like the idea here.  I like having the trees there, but they really almost seem to overwhelm the focus on the building imo.   Still, one of the better shots I"ve seen.', '2004-12-06 22:15:18.000000', NULL, 1),
(1049583, 125951, 14986, '<td valign="top">Very stark looking.  I wish the middle of the building didn''t have the details blown out so much.  Still, overall, I do like it.</td>', 'Very stark looking.  I wish the middle of the building didn''t have the details blown out so much.  Still, overall, I do like it.', '2004-12-06 22:16:13.000000', NULL, 1),
