(1049673, 126119, 15811, '<td valign="top">haha I like the one guy that drove off the road on the right heading toward the camera -- what''s up with that?</td>', 'haha I like the one guy that drove off the road on the right heading toward the camera -- what''s up with that?', '2004-12-06 23:10:59.000000', NULL, 1),
(1049678, 126142, 12674, '<td valign="top">This is really a perfect shot of the Big Chicken, very crisp and clear and unincumbered by all the utility wires hanging around the place.  I also shot the Big Chicken....had to clone out all of the other photographers.  There seems to be enough interest for a separate Big Chicken challenge.</td>', 'This is really a perfect shot of the Big Chicken, very crisp and clear and unincumbered by all the utility wires hanging around the place.  I also shot the Big Chicken....had to clone out all of the other photographers.  There seems to be enough interest for a separate Big Chicken challenge.', '2004-12-06 23:14:30.000000', NULL, 1),
(1049680, 126230, 12674, '<td valign="top">Brilliant idea!!  Awesome shot of the Big Chicken...a perfect image of folk art.  I was one of the other Big Chicken shooters.  You took quite a different approach that I really like.  I bet there''ll be enough interest now for a separate Big Chicken challenge...great shot!</td>', 'Brilliant idea!!  Awesome shot of the Big Chicken...a perfect image of folk art.  I was one of the other Big Chicken shooters.  You took quite a different approach that I really like.  I bet there''ll be enough interest now for a separate Big Chicken challenge...great shot!', '2004-12-06 23:17:16.000000', NULL, 1),
(1049736, 125627, 19952, '<td valign="top">Absolutely beautiful night shot and perfect for the landmark challenge. Really great photo!</td>', 'Absolutely beautiful night shot and perfect for the landmark challenge. Really great photo!', '2004-12-07 00:11:28.000000', NULL, 1),
(1049745, 126152, 19952, '<td valign="top">Great subject and excellent composition and exposure. Really nice job!</td>', 'Great subject and excellent composition and exposure. Really nice job!', '2004-12-07 00:23:16.000000', NULL, 1),
(1049762, 125024, 19503, '<td valign="top">I like the intense colors of the tower, but I can see some large connecting lighter circles in the sky, from post editing?. Make sure your monitor is calibrated correctly, unless it was intentional.</td>', 'I like the intense colors of the tower, but I can see some large connecting lighter circles in the sky, from post editing?. Make sure your monitor is calibrated correctly, unless it was intentional.', '2004-12-07 00:37:48.000000', NULL, 1),
