(1049766, 126038, 29486, '<td valign="top">Nice try but nah</td>', 'Nice try but nah', '2004-12-07 00:44:58.000000', NULL, 1),
(1049768, 126207, 19503, '<td valign="top">What a beautiful church and angle. B&amp;W works very well in this image, you have reached the full spectrum of light with the clouds at one end of the scale to the dark left corner on the other. If there is anything to nitpick on, it might be the right top corner which feels a little unnaturally dark, a smoother transition would have worked better imho. GJ</td>', 'What a beautiful church and angle. B&W works very well in this image, you have reached the full spectrum of light with the clouds at one end of the scale to the dark left corner on the other. If there is anything to nitpick on, it might be the right top corner which feels a little unnaturally dark, a smoother transition would have worked better imho. GJ', '2004-12-07 00:46:48.000000', NULL, 1),
(1049769, 126191, 29486, '<td valign="top">Nicely framed. Found photo to be fine but not special.</td>', 'Nicely framed. Found photo to be fine but not special.', '2004-12-07 00:47:13.000000', NULL, 1),
