(1053130, 126177, 6667, '<td valign="top">So simple so sweet!  Nicely done!</td>', 'So simple so sweet!  Nicely done!', '2004-12-08 20:40:05.000000', NULL, 1),
(1053131, 125791, 20779, '<td valign="top">What a stark, commanding image to draw us in and keep us there. Like good poetry or music, I can feel something differently each time I visit this image. There is a bleak, frigid barrenness depicted, but also an emerging hope in my eyes.</td>', 'What a stark, commanding image to draw us in and keep us there. Like good poetry or music, I can feel something differently each time I visit this image. There is a bleak, frigid barrenness depicted, but also an emerging hope in my eyes.', '2004-12-08 20:40:09.000000', NULL, 1),
(1053136, 126041, 20779, '<td valign="top">I feel that you will hear a lot about the highlights and processing of this, but I have to say that it is a stunning piece visually and just gleams with brilliance.</td>', 'I feel that you will hear a lot about the highlights and processing of this, but I have to say that it is a stunning piece visually and just gleams with brilliance.', '2004-12-08 20:42:10.000000', NULL, 1),
(1053151, 125854, 20779, '<td valign="top">Spectacular lighting and movement.</td>', 'Spectacular lighting and movement.', '2004-12-08 20:45:32.000000', NULL, 1),
(1053157, 126162, 20779, '<td valign="top">Very cool lighting and contrasts. I love the use of the negative space to create a clean image out of what could easily look cluttered by nature.</td>', 'Very cool lighting and contrasts. I love the use of the negative space to create a clean image out of what could easily look cluttered by nature.', '2004-12-08 20:47:34.000000', NULL, 1),
(1053164, 126051, 20779, '<td valign="top">Simply stunning and elegant. Perfect title that enhances it even further.</td>', 'Simply stunning and elegant. Perfect title that enhances it even further.', '2004-12-08 20:49:26.000000', NULL, 1),
