(1053532, 125957, 23458, '<td valign="top">The framing effect here is terrific... and the green cast whether because of the windows or photoshop is also really effective. 9.</td>', 'The framing effect here is terrific... and the green cast whether because of the windows or photoshop is also really effective. 9.', '2004-12-09 00:14:56.000000', NULL, 1),
(1053533, 126041, 29486, '<td valign="top">Pretty darn good.  It looks like the shutter was left open just a bit too long but still a great picture.</td>', 'Pretty darn good.  It looks like the shutter was left open just a bit too long but still a great picture.', '2004-12-09 00:15:05.000000', NULL, 1),
(1053536, 126051, 29486, '<td valign="top">Pretty cool. A good photo.</td>', 'Pretty cool. A good photo.', '2004-12-09 00:16:30.000000', NULL, 1),
(1053538, 126041, 23458, '<td valign="top">This is gorgeous, I do like the soft effect here, but can''t help feel it is perhaps a little overdone... maybe a little overprocessed or exposure is too long (??)  but otherwise great. 8.</td>', 'This is gorgeous, I do like the soft effect here, but can''t help feel it is perhaps a little overdone... maybe a little overprocessed or exposure is too long (??)  but otherwise great. 8.', '2004-12-09 00:17:05.000000', NULL, 1),
(1053539, 125030, 29486, '<td valign="top">OK, I guess I''ll buy that she''s a landmark. A bit over saturated. Decent attempt.</td>', 'OK, I guess I''ll buy that she''s a landmark. A bit over saturated. Decent attempt.', '2004-12-09 00:17:58.000000', NULL, 1),
