(1053958, 124877, 27482, '<td valign="top">Love this shot, great colours and framing.  I probably would have given it a 10 but IMO this doesn´t truly meet the challenge as I can´t make out any landmark except for that sign so I gave it a 9.</td>', 'Love this shot, great colours and framing.  I probably would have given it a 10 but IMO this doesn´t truly meet the challenge as I can´t make out any landmark except for that sign so I gave it a 9.', '2004-12-09 05:59:46.000000', NULL, 1),
(1053962, 125861, 19952, '<td valign="top">Really nice landmark shot and the people in the foreground give it a good perspective. Great job.</td>', 'Really nice landmark shot and the people in the foreground give it a good perspective. Great job.', '2004-12-09 06:10:37.000000', NULL, 1),
