(1056766, 126147, 6405, '<td valign="top">Excellent,9</td>', 'Excellent,9', '2004-12-10 23:16:12.000000', NULL, 1),
(1056778, 126182, 6405, '<td valign="top">You need more light on the subject being represented,maybe different time of the day,and would be nice the sky (background ) to be less plain.</td>', 'You need more light on the subject being represented,maybe different time of the day,and would be nice the sky (background ) to be less plain.', '2004-12-10 23:22:20.000000', NULL, 1),
(1056802, 126143, 20115, '<td valign="top">Very nice reflection in water.  Nice shot.</td>', 'Very nice reflection in water.  Nice shot.', '2004-12-10 23:44:19.000000', NULL, 1),
(1056803, 126038, 20115, '<td valign="top">This does not work for me.  Not really a landmark, leaf is lost in the snow, etc.</td>', 'This does not work for me.  Not really a landmark, leaf is lost in the snow, etc.', '2004-12-10 23:45:09.000000', NULL, 1),
(1056804, 125789, 20115, '<td valign="top">I like this ver much.</td>', 'I like this ver much.', '2004-12-10 23:45:33.000000', NULL, 1),
(1056806, 126167, 20115, '<td valign="top">This is great--from humble beginnings.</td>', 'This is great--from humble beginnings.', '2004-12-10 23:47:20.000000', NULL, 1),
(1056807, 125374, 20115, '<td valign="top">very nice--beautiful glow in sky matched by the reflection.  Look welcoming.</td>', 'very nice--beautiful glow in sky matched by the reflection.  Look welcoming.', '2004-12-10 23:48:27.000000', NULL, 1),
(1056808, 125587, 20115, '<td valign="top">This is so strange --looks like a painting.  Hope you put in comments on how you got this effect.</td>', 'This is so strange --looks like a painting.  Hope you put in comments on how you got this effect.', '2004-12-10 23:49:40.000000', NULL, 1),
(1056811, 125540, 20115, '<td valign="top">Please make notes about were this is.</td>', 'Please make notes about were this is.', '2004-12-10 23:51:27.000000', NULL, 1),
(1056820, 126240, 20115, '<td valign="top">this is beautiful.  how do you get the moon so clear.  Guess my lens is not strong enough.  The moon only looks like a big glow of light with out definition like this one.  I use a tripod, etc. but I cannot get any where near this shot.</td>', 'this is beautiful.  how do you get the moon so clear.  Guess my lens is not strong enough.  The moon only looks like a big glow of light with out definition like this one.  I use a tripod, etc. but I cannot get any where near this shot.', '2004-12-10 23:57:47.000000', NULL, 1),
(1056822, 125854, 20115, '<td valign="top">Beautiful shot, but does not quite make the challenge for me.</td>', 'Beautiful shot, but does not quite make the challenge for me.', '2004-12-10 23:58:51.000000', NULL, 1),
(1056825, 126114, 20115, '<td valign="top">This is an incredibly beautiful photo and well as frightening one.  Great job</td>', 'This is an incredibly beautiful photo and well as frightening one.  Great job', '2004-12-10 23:59:47.000000', NULL, 1),
(1056888, 125309, 18194, '<td valign="top">To me this has too high of contrast.  The sky is also blown out a fair bit.</td>', 'To me this has too high of contrast.  The sky is also blown out a fair bit.', '2004-12-11 01:40:50.000000', NULL, 1),
(1056895, 125540, 18194, '<td valign="top">I think you photographed this at the perfect time of day.  I also like the point of view very much.</td>', 'I think you photographed this at the perfect time of day.  I also like the point of view very much.', '2004-12-11 01:44:17.000000', NULL, 1),
(1056940, 126029, 12963, '<td valign="top">Love the look!! The combination of the Northern Lights and the shape give this a sci fi spaceship look..awesome job!</td>', 'Love the look!! The combination of the Northern Lights and the shape give this a sci fi spaceship look..awesome job!', '2004-12-11 02:31:34.000000', NULL, 1),
(1056942, 125150, 4767, '<td valign="top">nice photo.  where''s the mountain?</td>', 'nice photo.  where''s the mountain?', '2004-12-11 02:34:07.000000', NULL, 1),
(1056944, 126041, 4767, '<td valign="top">Lovely long exposure!</td>', 'Lovely long exposure!', '2004-12-11 02:34:50.000000', NULL, 1),
(1056945, 125854, 12963, '<td valign="top">Wonderful colors!!!! The lighting is gorgeous!!</td>', 'Wonderful colors!!!! The lighting is gorgeous!!', '2004-12-11 02:35:46.000000', NULL, 1),
(1056951, 126214, 4767, '<td valign="top">Patsville, eh?  Funny how it has become Nowheresville.  A great photo.  I like it a lot - tonality is good, composition is excellent, FINDING the place is extraordinary!</td>', 'Patsville, eh?  Funny how it has become Nowheresville.  A great photo.  I like it a lot - tonality is good, composition is excellent, FINDING the place is extraordinary!', '2004-12-11 02:39:56.000000', NULL, 1),
(1056952, 125309, 4767, '<td valign="top">Interesting effect - looks almost like a hand-colored shot.</td>', 'Interesting effect - looks almost like a hand-colored shot.', '2004-12-11 02:41:36.000000', NULL, 1),
(1056954, 126202, 4767, '<td valign="top">a popular bird in this competition, I notice.</td>', 'a popular bird in this competition, I notice.', '2004-12-11 02:42:25.000000', NULL, 1),
(1056962, 126242, 4767, '<td valign="top">I like the sharp foreground fading into the mist...</td>', 'I like the sharp foreground fading into the mist...', '2004-12-11 02:46:12.000000', NULL, 1),
(1056966, 126152, 4767, '<td valign="top">Now THAT is a tower worth visiting!  Few of these entries have made me want to travel to the Landmark, but... this is fascinating!</td>', 'Now THAT is a tower worth visiting!  Few of these entries have made me want to travel to the Landmark, but... this is fascinating!', '2004-12-11 02:48:59.000000', NULL, 1),
(1056968, 125425, 4767, '<td valign="top">Nice monochrome, great composition!</td>', 'Nice monochrome, great composition!', '2004-12-11 02:50:01.000000', NULL, 1),
(1056971, 125791, 12963, '<td valign="top">Very Powerful and moving...goood luck!!!</td>', 'Very Powerful and moving...goood luck!!!', '2004-12-11 02:50:46.000000', NULL, 1),
(1056974, 126272, 4767, '<td valign="top">I am so glad this is B&amp;W - it looks like an image from Life or Look taken in the era of their documentary highlights.  This grabs my heart and leaves me desolate.</td>', 'I am so glad this is B&W - it looks like an image from Life or Look taken in the era of their documentary highlights.  This grabs my heart and leaves me desolate.', '2004-12-11 02:53:54.000000', NULL, 1),
(1056977, 126299, 4767, '<td valign="top">What an outstanding humorous image!  I love it!</td>', 'What an outstanding humorous image!  I love it!', '2004-12-11 02:55:15.000000', NULL, 1),
(1056981, 125336, 4767, '<td valign="top">I love the blue of the shadow matching the sky.  And what an interesting composition!</td>', 'I love the blue of the shadow matching the sky.  And what an interesting composition!', '2004-12-11 02:56:22.000000', NULL, 1),
(1056985, 126291, 4767, '<td valign="top">Like the sunset, like the valley, like the exposure - not crazy about the frame.</td>', 'Like the sunset, like the valley, like the exposure - not crazy about the frame.', '2004-12-11 02:58:52.000000', NULL, 1),
(1056991, 125059, 4767, '<td valign="top">I wanna go BIGGER.  Good shot - I like the quandary it shows, but it needs to be a larger image or you''ll lose points.</td>', 'I wanna go BIGGER.  Good shot - I like the quandary it shows, but it needs to be a larger image or you''ll lose points.', '2004-12-11 03:01:46.000000', NULL, 1),
(1056993, 126142, 4767, '<td valign="top">a popular subject in this competition.</td>', 'a popular subject in this competition.', '2004-12-11 03:05:48.000000', NULL, 1),
(1056998, 126106, 4767, '<td valign="top">Interesting composition, great light, but if I hadn''t read the title, I might have missed the bridge.</td>', 'Interesting composition, great light, but if I hadn''t read the title, I might have missed the bridge.', '2004-12-11 03:07:57.000000', NULL, 1),
(1057002, 126028, 4767, '<td valign="top">I like the composition.  I have no clue what your subject is, but the power company is to be commended on the location of that power pole.</td>', 'I like the composition.  I have no clue what your subject is, but the power company is to be commended on the location of that power pole.', '2004-12-11 03:13:15.000000', NULL, 1),
(1057007, 126162, 4767, '<td valign="top">The lights on the top of the tower seem like glowing eyes on a Thai/Cambodian Buddha, who is wearing a pointed hat.His mouth is also slightly glowing.  I LIKE the photo - great sunset colors, nice silhouettes... but the top of it got my imagination  in gear.</td>', 'The lights on the top of the tower seem like glowing eyes on a Thai/Cambodian Buddha, who is wearing a pointed hat.His mouth is also slightly glowing.  I LIKE the photo - great sunset colors, nice silhouettes... but the top of it got my imagination  in gear.', '2004-12-11 03:18:12.000000', NULL, 1),
(1057009, 126302, 4767, '<td valign="top">Some days you''re the windshield, some days you''re the bug.  I HATE that sort of day!</td>', 'Some days you''re the windshield, some days you''re the bug.  I HATE that sort of day!', '2004-12-11 03:20:11.000000', NULL, 1),
(1057011, 125951, 4767, '<td valign="top">Interesting angle for this temple.</td>', 'Interesting angle for this temple.', '2004-12-11 03:21:54.000000', NULL, 1),
(1057012, 126014, 4767, '<td valign="top">The black frame doesn''t really add to the photo.  This Lady is about delicacy on a unique scale; the heavy black frame makes her look frumpy and fat, not élégante and strangely toujours à la mode.  <br/> <br/>Continuing to look at this photo, PLEASE tell me it''s a model/reproduction and NOT la Tour Eiffel en réalité.</td>', 'The black frame doesn''t really add to the photo.  This Lady is about delicacy on a unique scale; the heavy black frame makes her look frumpy and fat, not élégante and strangely toujours à la mode.   Continuing to look at this photo, PLEASE tell me it''s a model/reproduction and NOT la Tour Eiffel en réalité.', '2004-12-11 03:35:19.000000', NULL, 1),
(1057013, 126155, 4767, '<td valign="top">I''m a bad speller, but this is ridiculous!  Unless it''s Welch.  <br/> <br/>COOL clock!</td>', 'I''m a bad speller, but this is ridiculous!  Unless it''s Welch.   COOL clock!', '2004-12-11 03:36:30.000000', NULL, 1),
(1057014, 126181, 4767, '<td valign="top">Kind of a cool ''Star Wars Titles'' effect!</td>', 'Kind of a cool ''Star Wars Titles'' effect!', '2004-12-11 03:37:45.000000', NULL, 1),
(1057022, 125790, 4767, '<td valign="top">Interesting colors to distract the eye from the extraordinary composition.  Or is the composition detracting from enjoying the subtlties of the colors?</td>', 'Interesting colors to distract the eye from the extraordinary composition.  Or is the composition detracting from enjoying the subtlties of the colors?', '2004-12-11 04:20:12.000000', NULL, 1),
(1057024, 126184, 19959, '<td valign="top">Shame to crop the opera house. To me this is a more recognisable landmark for Sydney</td>', 'Shame to crop the opera house. To me this is a more recognisable landmark for Sydney', '2004-12-11 04:23:38.000000', NULL, 1),
(1057025, 125587, 4767, '<td valign="top">Almost surreal,  amazing leading lines, thin echoing the bold; strong colors - even in the deep shadows.  Then, the title adds to the strength of the photo.</td>', 'Almost surreal,  amazing leading lines, thin echoing the bold; strong colors - even in the deep shadows.  Then, the title adds to the strength of the photo.', '2004-12-11 04:25:04.000000', NULL, 1),
(1057028, 125627, 19959, '<td valign="top">You should have straightened the horizon. It distracts from what whould have been a winner..</td>', 'You should have straightened the horizon. It distracts from what whould have been a winner..', '2004-12-11 04:29:07.000000', NULL, 1),
(1057032, 125862, 4767, '<td valign="top">COOL!</td>', 'COOL!', '2004-12-11 04:39:10.000000', NULL, 1),
(1057033, 126191, 4767, '<td valign="top">NICE framing!  Thanks for showing Ottawa without highlighting the snow, let''s brag about the lovely aspects of the True North Strong &amp; free!</td>', 'NICE framing!  Thanks for showing Ottawa without highlighting the snow, let''s brag about the lovely aspects of the True North Strong & free!', '2004-12-11 04:41:18.000000', NULL, 1),
(1057034, 125797, 4767, '<td valign="top">incroyable!</td>', 'incroyable!', '2004-12-11 04:42:11.000000', NULL, 1),
(1057035, 126177, 4767, '<td valign="top">A sad, sad truth.  We do know this.  It''s become a scab on the face of our world.  Great photo. well exposed, extremely well laid out, but the subject matter depresses me.  It''s the Lowest Common Denominator in the whole world''s diet. 7</td>', 'A sad, sad truth.  We do know this.  It''s become a scab on the face of our world.  Great photo. well exposed, extremely well laid out, but the subject matter depresses me.  It''s the Lowest Common Denominator in the whole world''s diet. 7', '2004-12-11 04:47:42.000000', NULL, 1),
(1057036, 126255, 4767, '<td valign="top">which mission is this?</td>', 'which mission is this?', '2004-12-11 04:48:31.000000', NULL, 1),
(1057037, 125972, 10084, '<td valign="top">I really like that the height of the shot is at the same level as the animals. Gives a great feeling that you are there at the scene.  It would be interesting to see shots of the first bull with the reflection in the water if you have any after the challenge.</td>', 'I really like that the height of the shot is at the same level as the animals. Gives a great feeling that you are there at the scene.  It would be interesting to see shots of the first bull with the reflection in the water if you have any after the challenge.', '2004-12-11 04:51:51.000000', NULL, 1),
(1057038, 126283, 4767, '<td valign="top">popular place, apparently</td>', 'popular place, apparently', '2004-12-11 04:53:40.000000', NULL, 1),
(1057040, 126242, 10084, '<td valign="top">It would be interesting to see a black and white version of the scene. The scene itself and the composition is interesting but the dull colors of a hazy day makes it possibly better in b/w. The waves brings your eyes toward the lighthouse. Bonus points for that. "8"</td>', 'It would be interesting to see a black and white version of the scene. The scene itself and the composition is interesting but the dull colors of a hazy day makes it possibly better in b/w. The waves brings your eyes toward the lighthouse. Bonus points for that. "8"', '2004-12-11 04:55:19.000000', NULL, 1),
(1057042, 125861, 10084, '<td valign="top">Beautiful night colors makes this compositon very interesting.  The rails on the walkway leads ones eyes toward the main subject. Very nice.</td>', 'Beautiful night colors makes this compositon very interesting.  The rails on the walkway leads ones eyes toward the main subject. Very nice.', '2004-12-11 04:56:52.000000', NULL, 1),
(1057085, 126192, 14614, '<td valign="top">great timing - one of my favorites this challenge bol</td>', 'great timing - one of my favorites this challenge bol', '2004-12-11 08:28:48.000000', NULL, 1),
