(1058462, 126291, 9668, '<td valign="top">Great landscape/seascape/sunset shot, but a single landmard doesn''t stand out to me.</td>', 'Great landscape/seascape/sunset shot, but a single landmard doesn''t stand out to me.', '2004-12-12 17:30:45.000000', NULL, 1),
