(1058685, 125709, 1031, '<td valign="top">Exquisite contrast in architectural styles, well demonstrated by the composition.</td>', 'Exquisite contrast in architectural styles, well demonstrated by the composition.', '2004-12-12 21:55:21.000000', NULL, 1),
(1058688, 126040, 7485, '<td valign="top">Interesting looking building, but too much foreground and that half a bench on the left is distracting.</td>', 'Interesting looking building, but too much foreground and that half a bench on the left is distracting.', '2004-12-12 21:57:27.000000', NULL, 1),
(1058690, 126283, 1031, '<td valign="top">I''d have expected to find that in Boston -- it''s not a soybean ...</td>', 'I''d have expected to find that in Boston -- it''s not a soybean ...', '2004-12-12 21:58:14.000000', NULL, 1),
(1058695, 125442, 1031, '<td valign="top">Glad to see other people including trees in their building shots -- I like them there myself ...</td>', 'Glad to see other people including trees in their building shots -- I like them there myself ...', '2004-12-12 21:59:45.000000', NULL, 1),
(1058698, 125951, 7485, '<td valign="top">Almost like something out of a Hugh Ferriss drawing, excellent work!</td>', 'Almost like something out of a Hugh Ferriss drawing, excellent work!', '2004-12-12 22:02:01.000000', NULL, 1),
(1058702, 126126, 1031, '<td valign="top">I like it, but would maybe crop it from the right all the way to a square.</td>', 'I like it, but would maybe crop it from the right all the way to a square.', '2004-12-12 22:05:15.000000', NULL, 1),
(1058704, 125054, 7485, '<td valign="top">Great colors and bold symmetric design. I find this an even more striking image with the bottom half inch or so cropped off (just below the outer edge of the platform).</td>', 'Great colors and bold symmetric design. I find this an even more striking image with the bottom half inch or so cropped off (just below the outer edge of the platform).', '2004-12-12 22:05:53.000000', NULL, 1),
