(1058717, 126152, 7485, '<td valign="top">I swear I''ve seen this same angle on this tower in a DPC winner. But excellent anyway - 7</td>', 'I swear I''ve seen this same angle on this tower in a DPC winner. But excellent anyway - 7', '2004-12-12 22:13:27.000000', NULL, 1),
