(1058722, 125425, 12253, '<td valign="top">This is wonderful, and my pick for the Blue (appropriate color too).  Good luck!</td>', 'This is wonderful, and my pick for the Blue (appropriate color too).  Good luck!', '2004-12-12 22:17:41.000000', NULL, 1),
