(1065465, 126041, 5792, '<td valign="top">Amazing work. Great subject. Composed well and the soft touches work. Technically superior image. You are to be commended.<br/><br/><i>Message edited by author 2004-12-16 08:27:01.</i></td>', 'Amazing work. Great subject. Composed well and the soft touches work. Technically superior image. You are to be commended.', '2004-12-16 08:25:44.000000', '2004-12-16 08:27:01.000000', 0),
(1065468, 126294, 5792, '<td valign="top">Nice landscape capture of the dsidwell tradition.</td>', 'Nice landscape capture of the dsidwell tradition.', '2004-12-16 08:29:01.000000', NULL, 0),
(1065470, 125791, 5792, '<td valign="top">One of my top three choices for this challenge. Your choice of sepia and processing for a stark white background with reduced and sketchy detail is perfect for the message contained within this image. Great job! You have my admiration for this marvelous composition.</td>', 'One of my top three choices for this challenge. Your choice of sepia and processing for a stark white background with reduced and sketchy detail is perfect for the message contained within this image. Great job! You have my admiration for this marvelous composition.', '2004-12-16 08:33:22.000000', NULL, 0),
(1065770, 125627, 16219, '<td valign="top">Beautiful photo. St Paul''s is quite beautiful. I never realized that English Commuter Rail Stations looked so much like American Commuter Rail Stations. I had heard however, Churchill''s actual comment was "Mrs Paul''s must be shaved."</td>', 'Beautiful photo. St Paul''s is quite beautiful. I never realized that English Commuter Rail Stations looked so much like American Commuter Rail Stations. I had heard however, Churchill''s actual comment was "Mrs Paul''s must be shaved."', '2004-12-16 12:58:48.000000', NULL, 0),
